import "server-only";

import { createClient } from "@/lib/supabase/server";
import type { CompanyCardData } from "@/components/companies/company-card";

const CARD_COLUMNS =
  "id, slug, name, category, city, country, logo_url, cover_url, is_claimed, verified, rating, projects_completed";

function sanitize(term: string) {
  return term.replace(/[,()%]/g, " ").trim();
}

export type CompaniesQuery = {
  q?: string;
  /** Matched against the company's free-text category, case-insensitively. */
  category?: string;
  claimed?: boolean;
  page?: number;
  pageSize?: number;
};

export type CompaniesResult = {
  companies: CompanyCardData[];
  total: number;
  available: boolean;
};

/** Public business directory. Resilient to the companies table not existing
 * yet (returns available:false) so the app renders before 0006 is applied. */
export async function getCompanies(
  params: CompaniesQuery = {},
): Promise<CompaniesResult> {
  const { q, category, claimed, page = 1, pageSize = 24 } = params;
  const supabase = await createClient();

  let query = supabase
    .from("companies")
    .select(CARD_COLUMNS, { count: "exact" });

  const term = q ? sanitize(q) : "";
  if (term) {
    query = query.or(
      `name.ilike.%${term}%,category.ilike.%${term}%,city.ilike.%${term}%`,
    );
  }
  // Category is free text on the row, so this is a contains match rather than
  // an equality: "Real Estate Developer" should answer to "developer".
  const categoryTerm = category ? sanitize(category) : "";
  if (categoryTerm) query = query.ilike("category", `%${categoryTerm}%`);

  if (typeof claimed === "boolean") query = query.eq("is_claimed", claimed);

  const from = (page - 1) * pageSize;
  const { data, count, error } = await query
    .order("verified", { ascending: false })
    .order("created_at", { ascending: false })
    .range(from, from + pageSize - 1);

  if (error) return { companies: [], total: 0, available: false };

  return {
    companies: (data ?? []) as CompanyCardData[],
    total: count ?? 0,
    available: true,
  };
}

export async function getCompanyBySlug(slug: string) {
  const supabase = await createClient();
  const { data } = await supabase
    .from("companies")
    .select("*")
    .eq("slug", slug)
    .maybeSingle();
  return data;
}

/**
 * The companies a member may post as.
 *
 * Ownership only. Team accounts are not built, so "my companies" means the
 * ones this person created — and a job posted under a company nobody has
 * claimed would be a company page with somebody else's hiring on it.
 */
export async function getMyCompanies(
  userId: string,
): Promise<{ id: string; name: string; slug: string }[]> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("companies")
    .select("id, name, slug")
    .eq("owner_id", userId)
    .order("name", { ascending: true })
    .limit(50);

  return data ?? [];
}
